// Removes build outputs: the frontend bundle and the Rust target dir.
// Both are regenerated by the next build (`npm run build:web` / `npm run build`).
// Run with `npm run clean`. Deliberately keeps node_modules (dev dependency)
// and the cargo registry outside the repo.
import { rmSync } from 'node:fs'

// Resolved from this file, so running it from another directory is safe.
for (const dir of ['dist', 'src-tauri/target']) {
  rmSync(new URL(`../${dir}`, import.meta.url), { recursive: true, force: true })
  console.log(`removed ${dir}`)
}
